import { buildSectionPage } from '../../../utils/section-page.utils.js';
import '../project-dashboard/project-story-list/project-story-list.component.js';
import type { ProjectStoryList } from '../project-dashboard/project-story-list/project-story-list.component.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../../_shared/screen-status.js';

export class ProjectsStoriesScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;

        const page = buildSectionPage(this, 'Stories', 'projects', '/projects');
        const intro = document.createElement('p');
        intro.textContent = 'Tap a story to reveal its summary and metadata while keeping the list compact on mobile.';
        page.content.append(intro, this.statusNodes.errorNode);

        const stories = document.createElement('project-story-list') as ProjectStoryList;
        stories.setAttribute('project-id', 'motivation');
        page.content.appendChild(stories);
    }
}

if (!customElements.get('projects-stories-screen')) {
    customElements.define('projects-stories-screen', ProjectsStoriesScreen);
}
